/**
 * REAL-GRAMMAR SIZE GATE — docs/design/runtime-and-size-contract.md, rule 4.
 *
 * Every shipped variant of jess's four grammars (css, less, scss, jess) must stay
 * within 5x raw generated bytes per byte of its `grammar.ts`. The probes in
 * `size-guard.ts` never reached this scale, which is how a css artifact reached
 * 14x unseen.
 *
 * The grammars are the vendored snapshot, built as jess builds them
 * (`bench/jess/real-grammars.ts`). No assembly profile is configured: the default
 * static ranking must meet the ceiling on its own, and every variant must be VALID —
 * it loads, and a CST variant parses a stylesheet through a CST host. An AST
 * variant's reducers build `@jesscss/core` nodes, which are not vendored; jess's own
 * suites cover an AST parse.
 *
 * FAILS CLOSED: a lowering warning, a missing or invalid variant, or any variant
 * over the ceiling exits 1.
 *
 *   pnpm size:guard:jess
 */
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { DIALECTS, FIXTURE, VARIANTS, withBuiltSnapshot, type Dialect } from './jess/real-grammars.ts'

export const REAL_GRAMMAR_CEILING = 5

/** Valid in every dialect. */
const VALIDITY_INPUT = '.a { color: red; }\n'

export type VariantSize = {
  dialect: Dialect; variant: string; bytes: number; sourceBytes: number; ratio: number
  /** Loads, and (CST variants) parses `VALIDITY_INPUT` through a CST host. */
  valid: boolean
}

type Loaded = {
  grammar: Record<string, unknown>
  run: (entry: unknown, input: string, opts: object) => { ok: boolean; unconsumedFrom: number | null }
  cstBuildHost: unknown
}

export async function measureJessGrammars(): Promise<{ sizes: VariantSize[]; warnings: string[] }> {
  return withBuiltSnapshot(async snap => {
    const sizes: VariantSize[] = []
    for (const dialect of DIALECTS) {
      const sourceBytes = Buffer.byteLength(readFileSync(join(snap.root, dialect, 'grammar.ts')))
      for (const variant of Object.keys(VARIANTS)) {
        const { bytes } = await snap.shipped(dialect, variant)
        let valid = false
        try {
          const mod = await import(await snap.runnable(dialect, variant)) as Loaded
          const entry = mod.grammar['Stylesheet']
          valid = typeof entry === 'function' && (!variant.startsWith('cst') || (() => {
            const r = mod.run(entry, VALIDITY_INPUT, { build: mod.cstBuildHost })
            return r.ok && r.unconsumedFrom === null
          })())
        } catch { valid = false }
        sizes.push({ dialect, variant, bytes, sourceBytes, ratio: bytes / sourceBytes, valid })
      }
    }
    return { sizes, warnings: [...snap.warnings] }
  })
}

/** The verdict: every failure, named. Empty means green. */
export function realGrammarFailures(sizes: readonly VariantSize[], warnings: readonly string[]): string[] {
  const expected = DIALECTS.length * Object.keys(VARIANTS).length
  const failures = warnings.map(w => `lowering warning: ${w}`)
  if (sizes.length !== expected) failures.push(`expected ${expected} variants, measured ${sizes.length}`)
  for (const s of sizes) {
    if (!(s.bytes > 0)) failures.push(`${s.dialect} ${s.variant}: empty output`)
    if (!s.valid) failures.push(`${s.dialect} ${s.variant}: not valid (did not load, or a CST variant did not parse ${JSON.stringify(VALIDITY_INPUT)})`)
    if (s.ratio > REAL_GRAMMAR_CEILING) {
      failures.push(`${s.dialect} ${s.variant}: ${s.bytes.toLocaleString('en-US')} B is ${s.ratio.toFixed(2)}x its grammar.ts — over the ${REAL_GRAMMAR_CEILING}x ceiling`)
    }
  }
  return failures
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const source = JSON.parse(readFileSync(join(FIXTURE, 'SOURCE.json'), 'utf8')) as { commit: string }
  const { sizes, warnings } = await measureJessGrammars()
  console.log(`size-guard:jess  jess ${source.commit.slice(0, 9)}  ceiling ${REAL_GRAMMAR_CEILING}x raw bytes per grammar.ts byte`)
  for (const s of sizes) {
    const validity = !s.valid ? 'INVALID' : s.variant.startsWith('cst') ? 'loads, parses' : 'loads'
    console.log(`  ${`${s.dialect} ${s.variant}`.padEnd(20)} ${s.bytes.toLocaleString('en-US').padStart(11)} B  ${s.ratio.toFixed(2).padStart(5)}x  ${validity}`)
  }
  const failures = realGrammarFailures(sizes, warnings)
  if (failures.length > 0) {
    console.error(`size-guard:jess: FAILED\n  ${failures.join('\n  ')}`)
    process.exit(1)
  }
  console.log(`size-guard:jess: ok — ${sizes.length} variants, all within ${REAL_GRAMMAR_CEILING}x`)
}
